import { Link, useLocation } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import { toast } from "react-toastify";

const Navbar = () => {
  const { user, logout } = useAuth();
  const location = useLocation();

  const handleAuthAction = async () => {
    if (user) {
      const result = await logout();
      if (result.success) toast.success("Logged out successfully");
      else toast.error(result.error || "Logout failed");
    } else {
      window.location.href = "/login";
    }
  };

  // Styles for active link
  const isActive = (path) =>
    location.pathname === path
      ? "text-[#b2541a] font-semibold"
      : "text-gray-800 hover:text-[#b2541a] transition";

  return (
    <nav className="bg-white shadow-md border-b border-orange-200 relative">

      {/* Decorative Top Border */}
      <div className="absolute top-0 left-0 w-full h-[3px] bg-gradient-to-r from-[#7a3512] via-[#d97828] to-[#7a3512]"></div>

      <div className="container mx-auto px-6">
        <div className="flex justify-between items-center py-4">

          {/* Brand Logo */}
          <Link className="text-2xl font-bold text-[#b2541a] tracking-wide" to="/">
            Bharat Connect
          </Link>

          {/* Desktop Links */}
          <div className="hidden md:flex space-x-8 text-lg font-medium">

            <Link className={isActive("/")} to="/">
              Home
            </Link>
            <Link className={isActive("/map")} to="/map">
              Map
            </Link>
            <Link className={isActive("/products")} to="/products">
              Products
            </Link>
            <Link className={isActive("/innovations")} to="/innovations">
              Innovations
            </Link>
            <Link className={isActive("/articles")} to="/articles">
              Articles
            </Link>

            {/* Admin Button */}
            {user?.role === "admin" && (
              <Link
                to="/admin"
                className="bg-[#b2541a] text-white px-3 py-1 rounded-lg shadow hover:bg-[#8d3c11] transition"
              >
                Admin
              </Link>
            )}
          </div>

          {/* Right Side Auth Section */}
          <div className="hidden md:flex items-center space-x-4">

            {/* Welcome User */}
            {user && (
              <span className="text-gray-700">
                Welcome, <span className="font-semibold text-[#b2541a]">{user.name}</span>
              </span>
            )}

            {/* Logout/Login Btn */}
            <button
              onClick={handleAuthAction}
              className="px-5 py-2 bg-[#b2541a] text-white rounded-lg shadow hover:bg-[#8d3c11] transition font-medium"
            >
              {user ? "Logout" : "Login"}
            </button>
          </div>

          {/* Mobile Menu Button (for future expansion) */}
          <button className="md:hidden text-[#b2541a] hover:text-[#8d3c11]">
            <svg className="w-7 h-7" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M4 6h16M4 12h16M4 18h16"
              />
            </svg>
          </button>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
